class Posse < Formula
  desc "Dispatcher binding personas, env sets and recipes to herdr and beads"
  homepage "https://github.com/ranger360ai/posse"
  version "0.3.0"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "https://github.com/ranger360ai/posse/releases/download/v0.3.0/posse_0.3.0_darwin_arm64.tar.gz"
      sha256 "a37b22dc2278b517cb6229cb31c80046a8e2b21ea14cbf9853592b8a07b5f50a"
    end
    on_intel do
      url "https://github.com/ranger360ai/posse/releases/download/v0.3.0/posse_0.3.0_darwin_amd64.tar.gz"
      sha256 "7e4ebb11eda152eed34257a632d8edeed3ef6ea55fa780be8253e6a54aef6c11"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ranger360ai/posse/releases/download/v0.3.0/posse_0.3.0_linux_arm64.tar.gz"
      sha256 "9f7c653177ea339c90292f6128214af4a3a1be9166d4089c04101db96a80a497"
    end
    on_intel do
      url "https://github.com/ranger360ai/posse/releases/download/v0.3.0/posse_0.3.0_linux_amd64.tar.gz"
      sha256 "296ba7c220f6e9676f4f3105efd2bfb6d2e06e1b0799d80b4bf6efd1cdc7cb08"
    end
  end

  def install
    bin.install "posse"
    doc.install "README.md", "INSTALL.md"
  end

  # No `depends_on` for either substrate, on purpose.
  #
  #   herdr  is not in Homebrew at all, and its own installer refuses to run
  #          under a package manager.
  #   beads  IS in Homebrew — at 1.2.x, which is the WRONG one. 1.2 replaced
  #          the SQLite backend with embedded Dolt, does not read
  #          .beads/beads.db, and auto-inits a stale fork of your queue on the
  #          first call. A `depends_on "beads"` here would hand every new
  #          installer a silently forked work graph. posse pins 0.49.1.
  def caveats
    <<~EOS
      posse needs two substrates Homebrew does not install for it:

        herdr >= 0.8      https://herdr.dev
        bd (beads) 0.49.1 EXACTLY — the upstream release binary, NOT
                          `brew install beads` (that is 1.2.x, which cannot
                          read .beads/beads.db and forks your queue silently).

      Then stand up an instance:

        posse init
        posse version

      The cold-start runbook is #{doc}/INSTALL.md.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/posse version")
  end
end
